import numpy as np

class WavyValley:

    def __init__(self, dim=5):
        self.dim = dim

    def f(self, x):
        # Quadratic term to ensure global minimum at origin
        quadratic = np.sum(x**2)

        # Wavy barrier term with multiple frequencies
        wavy = 0.0
        for i in range(self.dim):
            wavy += np.sin(3 * np.pi * x[i]) * np.cos(5 * np.pi * x[i])

        # Combine terms with scaling to create interesting landscape
        return quadratic + 0.5 * wavy**2
